module tb;

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 10;  // any period works
  logic clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 1'b0;

  // ------------------------------------------------------------
  // DUT interface signals
  // ------------------------------------------------------------
  logic [15:0] prescale_cfg = 16'd1;
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;   // DUT output
  logic        txd;             // unused
  logic        busy;            // DUT output

  // ------------------------------------------------------------
  // Instantiate the AXI‑Stream UART transmitter
  // ------------------------------------------------------------
  uart_tx #(.DATA_WIDTH(8)) dut (
    .clk       (clk),
    .rst       (rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .txd       (txd),
    .busy      (busy),
    .prescale  (prescale_cfg)
  );

  // ------------------------------------------------------------
  // Simple helpers
  // ------------------------------------------------------------
  task automatic do_reset();
    rst = 1'b0;
    #10;
    rst = 1'b1;
    #10;
    rst = 1'b0;
    #10;
  endtask

  // Send one byte using the AXI‑Stream handshake
  task automatic send_byte(input byte unsigned data);
    s_axis_tdata  = data;
    s_axis_tvalid = 1'b1;
    // Wait until the DUT asserts s_axis_tready (handshake)
    wait (s_axis_tready == 1'b1);
    // De‑assert valid for the next transaction
    s_axis_tvalid = 1'b0;
  endtask

  // ------------------------------------------------------------
  // Test sequence
  // ------------------------------------------------------------
  initial begin
    // Initialise all driving signals
    prescale_cfg = 16'd1;
    s_axis_tdata = 8'h00;
    s_axis_tvalid = 1'b0;

    // Reset the DUT
    do_reset();

    // --------------------------------------------------------
    // Drive two back‑to‑back words at the minimum prescale (1)
    // --------------------------------------------------------
    // First word (arbitrary pattern)
    send_byte(8'hA5);
    // Immediately follow with a second word
    send_byte(8'h5A);

    // --------------------------------------------------------
    // Wait long enough for the coverage point to be observed.
    // From the DUT timing, the event occurs well within a few
    // hundred clock cycles after the second word is accepted.
    // --------------------------------------------------------
    repeat (300) @(posedge clk);

    // End simulation – the coverage point must have been hit.
    $finish;
  end

endmodule
